  const lights = new THREE.Group();
  lights.name = "Island 013 Cactus Canyon World look-dev lights";
  const hemi = new THREE.HemisphereLight(
    mode === 'reference' ? 0xfff0d6 : 0xf2f4ff,
    0x363b42,
    mode === 'grazing' ? 0.28 : mode === 'reference' ? 0.72 : 0.85,
  );
  lights.add(hemi);
  const key = new THREE.DirectionalLight(
    mode === 'reference' ? 0xffcf8a : 0xfff4e8,
    mode === 'grazing' ? 4.2 : mode === 'reference' ? 2.6 : 2.15,
  );
  if (mode === 'grazing') key.position.set(7.5, 1.1, 4.0);
  else if (mode === 'reference') key.position.set(-4.5, 7.5, 5.0);
  else key.position.set(-4.0, 6.0, 5.5);
  key.castShadow = true;
  key.shadow.mapSize.set(4096, 4096);
  key.shadow.bias = -0.00025;
  key.shadow.normalBias = 0.018;
  key.shadow.radius = 7;
  key.shadow.blurSamples = 24;
  key.shadow.camera.near = 0.5;
  key.shadow.camera.far = 30;
  key.shadow.camera.left = -2.6;
  key.shadow.camera.right = 2.6;
  key.shadow.camera.top = 2.6;
  key.shadow.camera.bottom = -2.6;
  key.shadow.camera.updateProjectionMatrix();
  lights.add(key);
  const fill = new THREE.DirectionalLight(0xa8c4ff, mode === 'grazing' ? 0.12 : 0.42);
  fill.position.set(4.0, 3.0, 3.5);
  lights.add(fill);
  const rim = new THREE.DirectionalLight(0xfff1c4, mode === 'grazing' ? 0.28 : 0.85);
  rim.position.set(0.5, 4.5, -6.0);
  lights.add(rim);
  lights.userData.reviewMode = mode;
  lights.userData.lightingFromPhoto = ["Warm late-day key light comes from upper-left/front-left and creates bright ochre crests with terracotta shadow sides.", "Peach sky fill lifts deep canyon shadows without flattening the value range.", "Low lavender/pink atmospheric haze separates distant buttes from the saturated playable mesa.", "Amber window practicals remain restrained and do not turn the scene into night.", "Soft contact shadows ground buildings, trestles, cacti, rails and props.", "ACES filmic tone mapping at restrained exposure protects bright sandstone crests and amber window detail."];
  lights.userData.lookDevTargets = {"qualityPriority": "procedural-reference-guided", "materialPass": {"albedoPaletteRequired": true, "roughnessVariationRequired": true, "normalOrBumpRequired": true, "localOverridesRequired": true, "referencePbrExtraction": {"requiredWhenSourceImagePresent": false, "acceptedLimitation": "The illustrated full-scene source contains baked sunset lighting, atmospheric haze, text and UI; whole-image inverse PBR extraction would not provide trustworthy isolated material maps."}}, "lightingPass": {"requiredTerms": ["key light", "fill light", "environment light", "exposure", "tone mapping", "background", "contact shadow"]}, "screenshotReview": ["phone overview", "map-stripped overview", "orbit left", "orbit right", "five landmark focuses", "L1 L2 L3 overview", "High versus Low and reduced motion"]};
  return lights;
